export type FlowInvocationStatus = "active" | "interrupted" | "completed" | "cancelled";

export type TimelineEntryType = "flow" | "agent" | "skill" | "block";

export type FlowTimelineEntry = {
  id: string;
  type: TimelineEntryType;
  // Id of the timeline subject: a flow id for flow entries, and the skill or
  // block id for Mantle entries — it feeds the default title rendering.
  flowId: string;
  flowName?: string;
  agentId?: string;
  skillId?: string;
  blockId?: string;
  status: FlowInvocationStatus;
  startTime: Date;
  exactStartTime: number;
  endTime?: Date;
};
